def transform(grid):
    h, w = len(grid), len(grid[0])
    anchor_top = min(r for r in range(h) if any(v == 8 for v in grid[r]))
    out = [[0] * w for _ in range(h)]
    for color in {v for row in grid for v in row if v != 0}:
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        top = min(r for r, c in cells)
        shift = anchor_top - top
        for r, c in cells:
            nr = r + shift
            if 0 <= nr < h:
                out[nr][c] = color
    return out
